CREATE OR REPLACE FUNCTION public.check_resume_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    BEGIN
      IF (SELECT COUNT(*) FROM candidate_resumes WHERE user_id = NEW.user_id) >= 3 THEN
        RAISE EXCEPTION 'Maximum 3 resumes allowed per user';
      END IF;
      RETURN NEW;
    END;
    $function$
